<?php require __DIR__.'/../app/bootstrap.php';
$q=trim($_GET['q']??'');$type=(int)($_GET['type']??0);$prog=(int)($_GET['prog']??0);
$sql="SELECT d.*,sp.name program,dt.name type FROM documents d LEFT JOIN study_programs sp ON sp.id=d.study_program_id LEFT JOIN document_types dt ON dt.id=d.type_id WHERE d.status='published'";$p=[];
if($q!==''){$sql.=" AND (d.title LIKE ? OR d.author LIKE ? OR d.keywords LIKE ? OR d.abstract LIKE ?)";$x="%$q%";$p=[$x,$x,$x,$x];}
if($type){$sql.=" AND d.type_id=?";$p[]=$type;}if($prog){$sql.=" AND d.study_program_id=?";$p[]=$prog;}
$sql.=" ORDER BY d.year DESC,d.id DESC LIMIT 50";$s=$pdo->prepare($sql);$s->execute($p);$docs=$s->fetchAll();$types=$pdo->query("SELECT * FROM document_types ORDER BY name")->fetchAll();$progs=$pdo->query("SELECT * FROM study_programs ORDER BY name")->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Repository STIKes Namira Madina</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f5f8fc;color:#172033}.nav{background:#073b8f;color:#fff;padding:17px 6%;display:flex;justify-content:space-between}.brand{font-weight:800}.hero{padding:65px 6%;background:#073b8f;color:#fff}.hero h1{font-size:42px}.search{max-width:1000px;display:grid;grid-template-columns:1fr 180px 180px auto;gap:8px}.search input,.search select,.search button{padding:13px;border:0;border-radius:8px}.search button{background:#ffd700;font-weight:800}.wrap{padding:35px 6%}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.card{background:#fff;padding:22px;border-radius:14px}.tag{color:#0750b8;background:#eaf2ff;border-radius:30px;padding:6px 10px;font-size:12px}.btn{display:inline-block;background:#073b8f;color:#fff;text-decoration:none;padding:10px 14px;border-radius:8px;margin-top:8px}</style></head><body><nav class="nav"><div class="brand">STIKes NAMIRA MADINA</div><div>REPOSITORY DIGITAL</div></nav><section class="hero"><h1>Repository STIKes Namira Madina</h1><p>Koleksi karya ilmiah dan pengetahuan institusi.</p><form class="search"><input name="q" value="<?=e($q)?>" placeholder="Cari judul, penulis, kata kunci..."><select name="type"><option value="0">Semua jenis</option><?php foreach($types as $t):?><option value="<?=$t['id']?>" <?=$type==$t['id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select><select name="prog"><option value="0">Semua prodi</option><?php foreach($progs as $p):?><option value="<?=$p['id']?>" <?=$prog==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select><button>CARI</button></form></section><main class="wrap"><h2>Koleksi Terbaru</h2><div class="grid"><?php foreach($docs as $d):?><article class="card"><span class="tag"><?=e($d['type'])?></span><h3><?=e($d['title'])?></h3><p><?=e($d['author'])?> · <?=$d['year']?></p><small><?=e($d['program']??'')?></small><br><a class="btn" href="document.php?id=<?=$d['id']?>">Lihat detail</a></article><?php endforeach;?></div></main></body></html>